#!/usr/bin/env node
// replay.mjs — dependency-free HTTP API replay verifier.
// Usage: node replay.mjs <manifest.json>
// Manifest shape:
// {
//   "server": "./sample-server.js",          // workspace-relative Node entry
//   "requests": [                            // ordered GET requests
//     { "path": "/health", "status": 200, "body": { "ok": true } }
//   ]
// }
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import process from "node:process";

const require = createRequire(import.meta.url);

function die(msg, code = 1) {
  process.stderr.write(`replay: error: ${msg}\n`);
  process.exit(code);
}

const manifestArg = process.argv[2];
if (!manifestArg) die("usage: node replay.mjs <manifest.json>");

let manifestPath = path.resolve(manifestArg);
if (!existsSync(manifestPath)) die(`manifest not found: ${manifestArg}`);
if (!manifestArg.endsWith(".json")) die(`manifest must be a .json file: ${manifestArg}`);

let manifest;
try {
  manifest = JSON.parse(require("node:fs").readFileSync(manifestPath, "utf8"));
} catch (e) {
  die(`malformed JSON in manifest: ${e.message}`);
}

if (typeof manifest.server !== "string" || manifest.server.length === 0) {
  die(`manifest field "server" must be a non-empty string (workspace-relative entry)`);
}
if (!Array.isArray(manifest.requests) || manifest.requests.length === 0) {
  die(`manifest field "requests" must be a non-empty array of GET requests`);
}
for (const [i, r] of manifest.requests.entries()) {
  if (!r || typeof r.path !== "string" || !r.path.startsWith("/")) {
    die(`requests[${i}].path must be a string starting with "/"`);
  }
  if (!Number.isInteger(r.status)) {
    die(`requests[${i}].status must be an integer`);
  }
  if (r.body === undefined || typeof r.body !== "object" || r.body === null || Array.isArray(r.body)) {
    die(`requests[${i}].body must be a JSON object`);
  }
}

// Resolve server entry relative to the workspace (cwd).
const serverEntry = path.resolve(manifest.server);
if (!existsSync(serverEntry)) die(`server entry not found: ${manifest.server}`);

const PORT = 0; // OS-assigned; child prints "LISTENING_ON_PORT=<N>" on stdout.

function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    return a.every((v, i) => deepEqual(v, b[i]));
  }
  if (typeof a !== "object") return false;
  const ka = Object.keys(a).sort();
  const kb = Object.keys(b).sort();
  if (ka.length !== kb.length || !ka.every((k, i) => k === kb[i])) return false;
  return ka.every((k) => deepEqual(a[k], b[k]));
}

const child = spawn(process.execPath, [serverEntry], {
  env: { ...process.env, PORT: String(PORT), HOST: "127.0.0.1" },
  stdio: ["ignore", "pipe", "pipe"],
});

let childOutput = "";
let childStderr = "";
child.stdout.on("data", (d) => (childOutput += d));
child.stderr.on("data", (d) => (childStderr += d));

function stopServer() {
  return new Promise((resolve) => {
    if (child.exitCode !== null || child.killed) return resolve();
    child.once("exit", resolve);
    child.kill("SIGTERM");
    setTimeout(() => {
      try { child.kill("SIGKILL"); } catch {}
      resolve();
    }, 2000).unref();
  });
}

async function main() {
  // Wait for the readiness line, with a timeout.
  const READY_TIMEOUT_MS = 10000;
  const startedAt = Date.now();
  let boundPort = null;
  while (boundPort === null) {
    const m = childOutput.match(/LISTENING_ON_PORT=(\d+)/);
    if (m) { boundPort = Number(m[1]); break; }
    if (child.exitCode !== null) {
      die(`server exited before becoming ready (code ${child.exitCode})${childStderr ? `: ${childStderr.trim()}` : ""}`);
    }
    if (Date.now() - startedAt > READY_TIMEOUT_MS) {
      die(`timeout: server did not report readiness within ${READY_TIMEOUT_MS}ms`);
    }
    await new Promise((r) => setTimeout(r, 50));
  }

  const base = `http://127.0.0.1:${boundPort}`;
  const failures = [];

  for (const [i, req] of manifest.requests.entries()) {
    const label = `#${i + 1} GET ${req.path}`;
    let res;
    try {
      res = await fetch(base + req.path, { signal: AbortSignal.timeout(5000) });
    } catch (e) {
      failures.push(`${label}: request failed: ${e.message}`);
      continue;
    }
    if (res.status !== req.status) {
      failures.push(`${label}: expected status ${req.status}, got ${res.status}`);
    }
    let parsed;
    try {
      parsed = await res.json();
    } catch (e) {
      failures.push(`${label}: response body is not valid JSON: ${e.message}`);
      continue;
    }
    if (!deepEqual(parsed, req.body)) {
      failures.push(`${label}: body mismatch\n  expected: ${JSON.stringify(req.body)}\n  observed: ${JSON.stringify(parsed)}`);
    }
  }

  if (failures.length === 0) {
    process.stdout.write(`${manifest.requests.length} checks passed\n`);
    await stopServer();
    process.exit(0);
  }
  for (const f of failures) process.stderr.write(`replay: FAIL ${f}\n`);
  process.stderr.write(`replay: ${manifest.requests.length - failures.length}/${manifest.requests.length} checks passed\n`);
  await stopServer();
  process.exit(1);
}

process.on("exit", () => { try { child.kill("SIGKILL"); } catch {} });
main().catch(async (e) => {
  process.stderr.write(`replay: error: ${e?.stack || e}\n`);
  await stopServer();
  process.exit(1);
