// Sample local API used by the manifests. Binds 127.0.0.1 on an OS-assigned
// port (PORT=0) and prints "LISTENING_ON_PORT=<N>" once ready.
import http from "node:http";

const host = process.env.HOST || "127.0.0.1";
const port = Number(process.env.PORT || 0);

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${host}:${port}`);
  const send = (status, obj) => {
    res.writeHead(status, { "content-type": "application/json" });
    res.end(JSON.stringify(obj));
  };
  if (url.pathname === "/health") return send(200, { ok: true });
  if (url.pathname === "/double") {
    const n = Number(url.searchParams.get("n"));
    if (!Number.isFinite(n)) return send(400, { error: "bad_n" });
    return send(200, { value: n * 2 });
  }
  send(404, { error: "not_found" });
});

server.listen(port, host, () => {
  const addr = server.address();
  process.stdout.write(`LISTENING_ON_PORT=${addr.port}\n`);
});

