import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';

const input = JSON.parse(fs.readFileSync(new URL('./skill-subrecipe-pilot-input.json', import.meta.url), 'utf8'));
const tempRoot = fs.realpathSync(os.tmpdir());
const root = fs.mkdtempSync(path.join(tempRoot, 'atoma-subrecipe-pilot-'));
const digest = (value) => createHash('sha256').update(value).digest('hex');
const cases = [];
try {
  const scenarios = [
    ['recorded-fixtures', null, true],
    ['stdout-mismatch', (m) => { m.entries[0].stdout = '999 checks passed\n'; }, false],
    ['exit-code-mismatch', (m) => { m.entries[1].exitCode = 0; }, false],
    ['stderr-mismatch', (m) => { m.entries[2].stderr = 'unexpected diagnostic\n'; }, false],
    ['empty-manifest', (m) => { m.entries = []; }, false],
    ['unsupported-http-probe', (m) => { m.entries = [{ probe: 'http', method: 'GET', path: '/health', status: 200 }]; }, false],
    ['missing-manifest', null, false],
  ];
  for (const [name, mutate, shouldPass] of scenarios) {
    const cwd = path.join(root, name);
    fs.mkdirSync(cwd);
    for (const file of input.files) {
      const destination = path.resolve(cwd, file.path);
      assert.ok(destination.startsWith(cwd + path.sep), 'Fixture must remain inside its scenario');
      fs.mkdirSync(path.dirname(destination), { recursive: true });
      fs.writeFileSync(destination, file.content);
    }
    fs.writeFileSync(path.join(cwd, '_skill.mjs'), input.script);
    const manifestPath = path.join(cwd, '.atoma-probes.json');
    if (mutate) {
      const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
      mutate(manifest);
      fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + '\n');
    }
    if (name === 'missing-manifest') fs.unlinkSync(manifestPath);
    const watched = [...input.files.map((f) => f.path), '_skill.mjs'];
    const fingerprints = () => Object.fromEntries(watched.map((f) => {
      const absolute = path.join(cwd, f);
      return [f, fs.existsSync(absolute) ? digest(fs.readFileSync(absolute)) : null];
    }));
    const before = fingerprints();
    const started = Date.now();
    const result = spawnSync(process.execPath, ['_skill.mjs', JSON.stringify('Recheck the recorded command probes without changing any file.')], {
      cwd, encoding: 'utf8', timeout: 15000, maxBuffer: 1024 * 1024,
    });
    assert.ifError(result.error);
    assert.equal(result.status, shouldPass ? 0 : 1, `${name}: ${result.stderr}`);
    if (shouldPass) {
      const envelope = JSON.parse(result.stdout);
      assert.equal(envelope.output.length, 3);
      assert.ok(envelope.output.every((entry) => entry.passed));
      assert.deepEqual(envelope.output.map((entry) => entry.actualExitCode), [0, 1, 1]);
      assert.match(envelope.summary, /== GROUND TRUTH ==/);
    } else {
      assert.equal(result.stdout, '', 'A failed comparison must not emit a success envelope');
      assert.ok(result.stderr.trim(), 'A failure must include a diagnostic');
    }
    assert.deepEqual(fingerprints(), before, 'Reverification must preserve fixture bytes and expectations');
    cases.push({ name, expectedExitCode: shouldPass ? 0 : 1, exitCode: result.status, durationMs: Date.now() - started, stdout: result.stdout, stderr: result.stderr, filesUnchanged: true });
  }
  const report = { checkedAt: new Date().toISOString(), node: process.version, platform: process.platform, source: 'exact script and fixture bytes retrieved through the production MCP traces', scriptSha256: digest(input.script), cases };
  fs.writeFileSync(new URL('./skill-subrecipe-pilot-local-results.json', import.meta.url), JSON.stringify(report, null, 2) + '\n');
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
} finally {
  const resolved = fs.realpathSync(root);
  assert.equal(path.dirname(resolved), tempRoot);
  assert.ok(path.basename(resolved).startsWith('atoma-subrecipe-pilot-'));
  fs.rmSync(resolved, { recursive: true, force: true });
}
